            if (error) {
                self._listening.emitError(error);
            } else {
                self._listening.emitSuccess(self);
            }
        });

        server.on("close", function (error) {
            if (error) {
                self._stopped.emitError(error);
            } else {
                self._stopped.emitSuccess(self);
            }
